import {mountWalkthrough} from './walkthrough.js';
import {sceneFingerprint} from './interior-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountInteriorStudio(bridge){
 let finishSelection='',finishFit='tile',finishSize=1;let active=false,section='walk',reference=null,crop=null,prompt='Warm contemporary interior, natural oak, soft linen, textured plaster and realistic daylight.',provider='openai',mode='room',wallId='',captured=null,capturedContext=null,jobs=[],settings=[],online=false,batch=false,stopBatch=false,currentJob=null,timer=null,viewing=null;
 const walk=mountWalkthrough({...bridge,onWalkChange:()=>{const b=$('#interior-start-walk');if(b)b.textContent=walk.active?'Exit walkthrough':'Enter walkthrough';}});
 const button=document.createElement('button');button.id='interior-studio-btn';button.className='rail-btn';button.innerHTML='<svg><use href="#i-camera"/></svg><span>Explore</span>';$('.rail').insertBefore(button,$('#model-studio-btn'));
 const overlay=document.createElement('section');overlay.className='ai-viewer';overlay.hidden=true;overlay.setAttribute('aria-label','AI render viewer');$('.canvas-area').append(overlay);
 const file=document.createElement('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.hidden=true;document.body.append(file);
 button.onclick=()=>{bridge.leaveCAD();active=true;button.classList.add('active');$$('[data-tab]').forEach(b=>b.classList.remove('active'));bridge.clearSelection();bridge.setView('3d');renderPanel();renderInspector();refreshJobs();};
 const deactivate=()=>{if(batch)stopBatch=true;active=false;button.classList.remove('active');walk.stop();closeViewer();bridge.restoreInspector();};
 for(const b of $$('[data-tab],#model-studio-btn'))b.addEventListener('click',deactivate,{capture:true});
 async function api(url,options={}){const res=await fetch(url,{...options,headers:{'Content-Type':'application/json','X-Hestia-Client':'studio',...options.headers}});const body=await res.json();if(!res.ok)throw Error(body.error||'The local image service is unavailable.');return body;}
 async function status(){try{const data=await api('/api/ai/status');settings=data.providers.filter(p=>p.id!=='imagerouter');online=true;if(!settings.find(p=>p.id===provider)?.configured)provider=settings.find(p=>p.configured)?.id||provider;}catch{online=false;settings=[];}if(active)renderPanel();}
 function context(){return {projectId:bridge.getProject().id,floorId:bridge.getFloorId(),sceneFingerprint:sceneFingerprint(bridge.getProject(),bridge.getFloor())};}
 function sameContext(c){const now=context();return c&&now.projectId===c.projectId&&now.floorId===c.floorId&&now.sceneFingerprint===c.sceneFingerprint;}
 async function refreshJobs(){if(!online)return;try{const c=context();const data=await api(`/api/ai/jobs?projectId=${encodeURIComponent(c.projectId)}&floorId=${encodeURIComponent(c.floorId)}`);if(context().projectId!==c.projectId||context().floorId!==c.floorId)return;jobs=data.jobs;if(active)renderInspector();const running=jobs.find(j=>['running','queued'].includes(j.status));if(running&&!batch){clearTimeout(timer);timer=setTimeout(refreshJobs,2500);}}catch(error){bridge.toast(error.message);}}
 function tabs(){return `<div class="chips">${[['walk','Walkthrough'],['ai','AI renders'],['reference','Reference']].map(([id,label])=>`<button class="chip ${section===id?'active':''}" data-interior-tab="${id}">${label}</button>`).join('')}</div>`;}
 function wallsOptions(){return bridge.getFloor().walls.map((w,i)=>`<option value="${esc(w.id)}" ${wallId===w.id?'selected':''}>Wall ${i+1} · ${Math.hypot(w.x2-w.x1,w.z2-w.z1).toFixed(1)} m</option>`).join('');}
 function renderPanel(){if(!active)return;if(mode==='wall'&&!bridge.getFloor().walls.some(w=>w.id===wallId))wallId=bridge.getFloor().walls[0]?.id||'';$('#panel-eyebrow').textContent='STEP INSIDE YOUR IDEAS';$('#panel-title').textContent='Interior experience';$('#library-count').hidden=true;
  let html=tabs();
  if(section==='walk')html+=`<div class="interior-hero"><span class="eyebrow">YOUR FLOOR, AT EYE LEVEL</span><h2>Make yourself<br>at home.</h2><p>Walk through the actual model, then create AI images from the views you love.</p></div><button id="interior-start-walk" class="button primary full-width">${walk.active?'Exit walkthrough':'Enter walkthrough'}</button><p class="panel-copy">Drag to look around. WASD or arrow keys move. Q/E turn. Use the floor map or choose a room below to jump.</p><div class="interior-room-list">${bridge.getFloor().rooms.map(r=>`<button class="button subtle" data-jump-room="${esc(r.id)}"><span>${esc(r.name)}</span><span>↗</span></button>`).join('')||'<p class="panel-copy">Draw a room in Build to create your first walking space.</p>'}</div><p class="small-label">Walls and door openings constrain movement. Room jumps can cross closed boundaries; furniture collision and stairs are not simulated.</p>`;
  if(section==='ai')html+=`<p class="panel-copy">Turn a view of your 3D house into an AI interior image. Capture first, then describe the finish.</p><label class="field">Image provider<select id="interior-provider">${(settings.length?settings:[{id:'openai',name:'OpenAI'},{id:'gemini',name:'Google Gemini'},{id:'compatible',name:'OpenAI-compatible'}]).map(p=>`<option value="${p.id}" ${provider===p.id?'selected':''}>${esc(p.name)}${p.configured?' · ready':' · setup needed'}</option>`).join('')}</select></label><button id="interior-settings" class="button subtle full-width">Provider connection settings</button><label class="field interior-gap">Design target<select id="interior-mode"><option value="room" ${mode==='room'?'selected':''}>Whole room / viewpoint</option><option value="wall" ${mode==='wall'?'selected':''}>Selected wall surface</option></select></label>${mode==='wall'?`<label class="field interior-gap">Wall to redesign<select id="interior-wall">${wallsOptions()}</select></label><button id="interior-face-wall" class="button subtle full-width">Look toward this wall</button><p class="small-label">OpenAI uses a wall mask; Gemini uses a region guide. Results can still change details beyond the intended area.</p>`:''}<button id="interior-capture" class="button subtle full-width">${captured?'Recapture this viewpoint':'Capture this viewpoint'}</button>${captured?`<img class="interior-preview" src="${captured.source}" alt="Captured model viewpoint"/>${captured.mask?`<p class="small-label">Wall mask · transparent area can be edited</p><img class="interior-preview interior-mask" src="${captured.mask}" alt="Wall edit mask"/>`:''}`:''}<label class="field interior-gap">Design prompt<textarea id="interior-prompt" rows="5" maxlength="3500">${esc(prompt)}</textarea></label><p class="small-label">${reference?'Your reference image will be sent with the captured view.':'Optional: add a Pinterest/downloaded image in Reference.'}</p><button id="interior-generate" class="button primary full-width" ${batch?'disabled':''}>Generate this view</button><div class="separator"></div><button id="interior-floor-tour" class="button subtle full-width" ${batch?'disabled':''}>Generate floor tour · ${bridge.getFloor().rooms.length*4} images</button>${batch?'<button id="interior-stop-batch" class="button subtle full-width">Stop after current image</button>':''}<p id="interior-progress" class="small-label">${batch?'Generating viewpoints one at a time…':'Floor tours capture four directions in each room. Each image is a separate API request.'}</p><p class="small-label">Generate sends the captured image, optional reference, mask and prompt to your selected provider. Provider charges apply. No automatic generation or paid fallback.</p>`;
  if(section==='reference')html+=`<p class="panel-copy">Upload a saved Pinterest image or your own inspiration photo. Use it as an AI style reference, or crop a texture and apply it to the actual model.</p><button id="interior-upload" class="button primary full-width">Upload reference image</button>${reference?`<img class="interior-preview" src="${reference}" alt="Uploaded design reference"/><button id="interior-crop" class="button subtle full-width">Crop a material / wallpaper</button><button id="interior-clear-reference" class="button subtle full-width">Remove reference</button>${crop?`<img class="interior-preview" src="${crop}" alt="Cropped finish"/>`:''}<div class="separator"></div><label class="field">Apply to<select id="interior-finish-target">${bridge.getFloor().walls.map((w,i)=>`<option value="wall:${esc(w.id)}">Wall ${i+1}</option>`).join('')}${bridge.getFloor().rooms.map(r=>`<option value="room:${esc(r.id)}">Floor · ${esc(r.name)}</option>`).join('')}</select></label><label class="field interior-gap">Image fit<select id="interior-fit"><option value="tile">Repeat as a texture</option><option value="stretch">Stretch to surface</option></select></label><label class="field interior-gap">Tile size (meters)<input id="interior-tile-size" type="number" value="1" min=".1" max="20" step=".1"/></label><button id="interior-apply-finish" class="button primary full-width">Apply finish to 3D model</button><button id="interior-remove-finish" class="button subtle full-width">Remove selected finish</button><p class="small-label">This applies the image directly as a surface material. A full room photograph will look like a photograph on that surface; crop a texture for better results. Changes are saved with the project and support Undo.</p>`:'<div class="interior-empty">A little inspiration goes a long way.<br>PNG, JPEG or WebP · up to 10 MB</div>'}`;
  $('#panel-content').innerHTML=html;if($('#interior-finish-target')){if(finishSelection&&[...$('#interior-finish-target').options].some(o=>o.value===finishSelection))$('#interior-finish-target').value=finishSelection;$('#interior-fit').value=finishFit;$('#interior-tile-size').value=finishSize;$('#interior-finish-target').onchange=e=>finishSelection=e.target.value;}
  for(const b of $$('[data-interior-tab]'))b.onclick=()=>{section=b.dataset.interiorTab;renderPanel();refreshJobs();};
  for(const b of $$('[data-jump-room]'))b.onclick=()=>safe(()=>walk.jump(b.dataset.jumpRoom));
  $('#interior-start-walk')?.addEventListener('click',()=>safe(()=>walk.active?walk.stop():walk.start()));
  $('#interior-upload')?.addEventListener('click',()=>file.click());$('#interior-crop')?.addEventListener('click',cropDialog);$('#interior-clear-reference')?.addEventListener('click',()=>{reference=crop=null;renderPanel();});
  $('#interior-apply-finish')?.addEventListener('click',()=>safe(applyFinish));$('#interior-remove-finish')?.addEventListener('click',()=>safe(()=>{const o=finishTarget();bridge.mutate(()=>delete o.finish);}));
  $('#interior-provider')?.addEventListener('change',e=>provider=e.target.value);$('#interior-mode')?.addEventListener('change',e=>{mode=e.target.value;captured=null;renderPanel();});$('#interior-wall')?.addEventListener('change',e=>{wallId=e.target.value;captured=null;});
  if(mode==='wall'&&!wallId)wallId=bridge.getFloor().walls[0]?.id||'';
  $('#interior-face-wall')?.addEventListener('click',()=>safe(faceWall));$('#interior-settings')?.addEventListener('click',connectionDialog);$('#interior-capture')?.addEventListener('click',()=>safe(capture));$('#interior-prompt')?.addEventListener('input',e=>prompt=e.target.value);
  if(batch)for(const control of $('#panel-content').querySelectorAll('input,select,textarea,button'))control.disabled=control.id!=='interior-stop-batch';
  $('#interior-generate')?.addEventListener('click',()=>generateOne().catch(e=>bridge.toast(e.message)));$('#interior-floor-tour')?.addEventListener('click',confirmTour);$('#interior-stop-batch')?.addEventListener('click',()=>{stopBatch=true;bridge.toast('The current request will finish; remaining viewpoints are stopped.');});
 }
 function safe(fn){try{return fn();}catch(error){bridge.toast(error.message);}}
 function finishTarget(){const [kind,id]=$('#interior-finish-target').value.split(':');const target=bridge.getFloor()[kind==='wall'?'walls':'rooms'].find(o=>o.id===id);if(!target)throw Error('Select a surface first.');return target;}
 function applyFinish(){finishSelection=$('#interior-finish-target').value;finishFit=$('#interior-fit').value;finishSize=Number($('#interior-tile-size').value);const target=finishTarget(),size=Number($('#interior-tile-size').value),fit=$('#interior-fit').value;if(!Number.isFinite(size)||size<.1||size>20)throw Error('Tile size must be between 0.1 and 20 meters.');bridge.mutate(()=>target.finish={src:crop||reference,fit,tileSize:size});bridge.toast('Finish applied to your model. Undo restores the previous surface.');}
 file.onchange=async()=>{const f=file.files[0];file.value='';if(!f)return;try{if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>10*1024*1024)throw Error('Use a PNG, JPEG or WebP smaller than 10 MB.');const bitmap=await createImageBitmap(f);const ratio=Math.min(1,1400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();reference=canvas.toDataURL('image/jpeg',.82);if(reference.length>1400000)throw Error('This image is too detailed. Crop or reduce its size first.');crop=null;renderPanel();bridge.toast('Reference ready. It is sent to a provider only when you generate.');}catch(e){bridge.toast(e.message);}};
 function cropDialog(){bridge.modal('<span class="eyebrow">EXTRACT A FINISH</span><h2>Keep the detail you love.</h2><p>Drag a rectangle around a clean material patch, then use the selection.</p><canvas id="reference-crop-canvas" width="480" height="320" aria-label="Drag to crop a material"></canvas><button id="reference-crop-use" class="button primary full-width">Use selected crop</button>');const canvas=$('#reference-crop-canvas'),ctx=canvas.getContext('2d'),img=new Image();let a=null,b=null,dragging=false;const draw=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);if(a&&b){ctx.strokeStyle='#d3aaff';ctx.lineWidth=2;ctx.strokeRect(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(b.x-a.x),Math.abs(b.y-a.y));}};img.onload=()=>{canvas.height=Math.max(60,Math.round(480*img.height/img.width));draw();};img.src=reference;const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(canvas.width,(e.clientX-r.left)*canvas.width/r.width)),y:Math.max(0,Math.min(canvas.height,(e.clientY-r.top)*canvas.height/r.height))};};canvas.onpointerdown=e=>{a=b=point(e);dragging=true;canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(dragging){b=point(e);draw();}};canvas.onpointerup=e=>{b=point(e);dragging=false;draw();};$('#reference-crop-use').onclick=()=>safe(()=>{if(!a||!b||Math.abs(a.x-b.x)<8||Math.abs(a.y-b.y)<8)throw Error('Drag a larger crop first.');const out=document.createElement('canvas');out.width=Math.round(Math.abs(a.x-b.x));out.height=Math.round(Math.abs(a.y-b.y));out.getContext('2d').drawImage(img,Math.min(a.x,b.x)*img.width/canvas.width,Math.min(a.y,b.y)*img.height/canvas.height,out.width*img.width/canvas.width,out.height*img.height/canvas.height,0,0,out.width,out.height);crop=out.toDataURL('image/jpeg',.88);$('#modal').close();renderPanel();});}
 function connectionDialog(){bridge.modal(`<span class="eyebrow">YOUR IMAGE SERVICES</span><h2>Choose where to create.</h2><p>Set keys privately in a local <code>.env</code> file beside <code>server.mjs</code>, then restart Hestia. Copy the supplied <code>.env.example</code> to get started. Keys are never stored in your project or sent to the browser.</p><div class="interior-provider-list">${settings.map(p=>`<p><strong>${esc(p.name)}</strong> · ${p.configured?'Configured':'Not configured'}<br><small>${esc(p.model||'Choose an image-edit model')}</small></p>`).join('')}</div><p>OpenAI: <code>OPENAI_API_KEY</code><br>Gemini: <code>GEMINI_API_KEY</code><br>Compatible service: <code>HESTIA_COMPATIBLE_API_KEY</code>, <code>HESTIA_COMPATIBLE_EDIT_URL</code>, <code>HESTIA_COMPATIBLE_MODEL</code>.</p><p>A compatible service must accept multipart image edits and return base64 images. API access, model availability and billing depend on the provider account. This app does not use your ChatGPT/Gemini website sign-in.</p><button id="interior-refresh-status" class="button primary full-width">Refresh connection status</button>`);$('#interior-refresh-status').onclick=async()=>{await status();$('#modal').close();};}
 function faceWall(){const w=bridge.getFloor().walls.find(w=>w.id===wallId);if(!w)throw Error('Choose a wall.');if(!walk.active)walk.start();const s=walk.state(),dx=(w.x1+w.x2)/2-s.position[0],dz=(w.z1+w.z2)/2-s.position[2];s.yaw=Math.atan2(-dx,-dz);s.pitch=0;walk.restore(s);}
 function capture(){closeViewer();captured=walk.capture(mode==='wall'?wallId:null);capturedContext=context();renderPanel();bridge.toast('Viewpoint captured. Your next render uses this exact source image.');}
 function providerReady(){if(!online||!settings.find(p=>p.id===provider)?.configured)throw Error('Configure the selected image provider first. Open Provider connection settings.');if(!prompt.trim())throw Error('Describe the interior you want.');}
 async function submit(shot,c){providerReady();if(!sameContext(c))throw Error('The floor model changed. Capture a fresh viewpoint.');const job=await api('/api/ai/jobs',{method:'POST',body:JSON.stringify({...c,...shot,provider,prompt,mode,wallId:mode==='wall'?wallId:null,reference})});currentJob=job.id;await refreshJobs();return job;}
 async function generateOne(){providerReady();if(batch)return;if(!captured)capture();await submit(captured,capturedContext);bridge.toast('AI render started. You can keep exploring while it generates.');}
 function confirmTour(){safe(()=>{providerReady();if(!bridge.getFloor().rooms.length)throw Error('Add a room first.');if(mode==='wall')throw Error('Choose Whole room / viewpoint for a floor tour.');const count=bridge.getFloor().rooms.length*4;bridge.confirm('Generate '+count+' AI images?','This sends four viewpoints per room, your prompt and optional reference to '+settings.find(p=>p.id===provider).name+'. Each image is a separate request that may incur provider charges. You can stop after the current image.',()=>runTour().catch(e=>bridge.toast(e.message)));});}
 async function runTour(){if(batch)return;batch=true;stopBatch=false;const c={...context(),tourId:crypto.randomUUID()},rooms=[...bridge.getFloor().rooms],old=walk.active?walk.state():null;let completed=0;renderPanel();try{for(const room of rooms)for(const angle of [0,Math.PI/2,Math.PI,Math.PI*1.5]){if(stopBatch)return;if(!sameContext(c))throw Error('The model changed. The remaining tour renders were stopped.');walk.jump(room.id,angle);const shot=walk.capture();const job=await submit(shot,c);let state=job;while(['queued','running'].includes(state.status)){await new Promise(r=>setTimeout(r,2000));state=await api('/api/ai/jobs/'+job.id);}if(state.status!=='completed')throw Error(state.error||'The tour stopped because an image failed.');completed++;const label=$('#interior-progress');if(label)label.textContent=`${completed} of ${rooms.length*4} images completed`;await refreshJobs();}}finally{batch=false;currentJob=null;if(old&&sameContext(c))walk.restore(old);if(active)renderPanel();await refreshJobs();bridge.toast(completed+' tour images completed.');}}
 function closeViewer(){overlay.hidden=true;overlay.innerHTML='';viewing=null;}
 function showJob(job){if(job.status!=='completed')return;walk.stop();viewing=job;const complete=jobs.filter(j=>j.status==='completed'&&(!job.tourId||j.tourId===job.tourId));const rooms=bridge.getFloor().rooms.filter(r=>complete.some(j=>j.roomId===r.id));const at=rooms.findIndex(r=>r.id===job.roomId);overlay.hidden=false;
 overlay.innerHTML=`<div class="ai-viewer-toolbar"><strong>AI interpretation · ${esc(job.providerName)}</strong><button class="button subtle" id="ai-return-model">Return to 3D model</button></div><img id="ai-tour-image" src="/api/ai/jobs/${job.id}/result" alt="AI interior interpretation"/><div class="ai-viewer-actions"><button class="button subtle" id="ai-tour-prev">← Previous room</button><select id="ai-tour-room" aria-label="AI tour room">${rooms.map(r=>`<option value="${esc(r.id)}" ${r.id===job.roomId?'selected':''}>${esc(r.name)}</option>`).join('')}</select><button class="button subtle" id="ai-tour-next">Next room →</button></div><div class="ai-viewer-actions"><button class="button subtle" id="ai-tour-left">↶ Look left</button><span>Drag image to change direction</span><button class="button subtle" id="ai-tour-right">Look right ↷</button></div><p>Linked viewpoint images, not a continuous AI 3D world. Switch to the model to look and walk freely.</p>`;
 const angleDistance=(a,b)=>Math.abs(Math.atan2(Math.sin(a-b),Math.cos(a-b)));
 const choose=(roomId,yaw)=>{const candidates=complete.filter(j=>j.roomId===roomId).sort((a,b)=>angleDistance(a.camera.yaw,yaw)-angleDistance(b.camera.yaw,yaw));if(candidates.length)showJob(candidates[0]);};
 $('#ai-return-model').onclick=()=>safe(()=>{closeViewer();if(job.floorId!==bridge.getFloorId())throw Error('Open the original floor first.');walk.restore(job.camera);});
 $('#ai-tour-prev').onclick=()=>{if(rooms.length)choose(rooms[(at-1+rooms.length)%rooms.length].id,job.camera.yaw);};$('#ai-tour-next').onclick=()=>{if(rooms.length)choose(rooms[(at+1)%rooms.length].id,job.camera.yaw);};$('#ai-tour-room').onchange=e=>choose(e.target.value,job.camera.yaw);
 const turn=delta=>choose(job.roomId,job.camera.yaw+delta);$('#ai-tour-left').onclick=()=>turn(Math.PI/2);$('#ai-tour-right').onclick=()=>turn(-Math.PI/2);let start=null;$('#ai-tour-image').onpointerdown=e=>{start=e.clientX;e.preventDefault();e.target.setPointerCapture(e.pointerId);};$('#ai-tour-image').onpointerup=e=>{if(start!==null&&Math.abs(e.clientX-start)>50)turn(e.clientX>start?-Math.PI/2:Math.PI/2);start=null;};
 }
 function renderInspector(){if(!active)return;$('#inspector').classList.add('has-selection');$('#inspector-content').innerHTML=`<span class="eyebrow">FROM MODEL TO MOOD</span><h2>Your render collection.</h2><p class="panel-copy">Saved on this PC, linked to the floor and camera that inspired each image.</p><button id="interior-refresh-gallery" class="button subtle full-width">Refresh renders</button><div class="interior-gallery">${jobs.map(job=>`<article><div class="interior-job-heading"><strong>${esc(job.providerName)}</strong><span>${esc(job.status)}</span></div>${job.status==='completed'?`<button data-open-render="${job.id}"><img src="/api/ai/jobs/${job.id}/result" alt="Generated interior"/></button>`:`<div class="interior-empty">${job.status==='failed'||job.status==='interrupted'?esc(job.error||'Render did not finish.'):'Creating your interior image…'}</div>`}<p>${esc(job.prompt)}</p>${job.sceneFingerprint!==context().sceneFingerprint?'<p class="interior-stale">Model changed since this image was created.</p>':''}${job.status==='completed'?`<button class="button subtle" data-compare-render="${job.id}">Compare with model</button><a class="button subtle" href="/api/ai/jobs/${job.id}/result" download="hestia-${job.id}.${job.mime==='image/jpeg'?'jpg':job.mime==='image/webp'?'webp':'png'}">Download image</a>`:''}</article>`).join('')||'<div class="interior-empty">Your next perspective starts here.<br>AI renders will appear after you connect a provider and generate.</div>'}</div><p class="small-label">AI images may reinterpret geometry and differ between viewpoints. They do not alter the editable 3D model. Applied reference finishes do.</p>`;
  $('#interior-refresh-gallery').onclick=refreshJobs;for(const b of $$('[data-open-render]'))b.onclick=()=>showJob(jobs.find(j=>j.id===b.dataset.openRender));for(const b of $$('[data-compare-render]'))b.onclick=()=>compare(jobs.find(j=>j.id===b.dataset.compareRender));
 }
 function compare(job){bridge.modal(`<span class="eyebrow">SAME CAMERA, TWO INTERPRETATIONS</span><h2>Model & AI render</h2><p>${esc(job.prompt)}</p><div class="interior-compare"><figure><img src="/api/ai/jobs/${job.id}/source" alt="Original model view"/><figcaption>Original model</figcaption></figure><figure><img src="/api/ai/jobs/${job.id}/result" alt="AI interpretation"/><figcaption>AI interpretation · ${esc(job.providerName)}</figcaption></figure></div><button id="interior-open-tour" class="button primary full-width">Explore linked images</button>`);$('#interior-open-tour').onclick=()=>{$('#modal').close();showJob(job);};}
 let lastContext=context().projectId+'/'+context().floorId;function refresh(){const c=context(),key=c.projectId+'/'+c.floorId;if(key!==lastContext){lastContext=key;stopBatch=true;jobs=[];captured=null;wallId='';walk.stop();closeViewer();refreshJobs();}if(captured&&!sameContext(capturedContext))captured=null;if(active){renderPanel();renderInspector();}}
 status();
 return {get active(){return active;},renderPanel,renderInspector,refresh,walk,deactivate};
}
